command:
if (args[0] === "on") {

const distance = Number(args[1]) || 5;

const lastArg = args[args.length - 1];
const triggeringActor = game.actors.get(lastArg?.actorId);
  const triggeringUser = [... game.users].filter(u => u.character?.id === triggeringActor.id)[0];
// Cible(s) du joueur déclencheur (et pas du GM)
const targets = triggeringUser ? Array.from(triggeringUser.targets) : [];
const target = targets[0];

if (!target) {
  ui.notifications.warn(game.i18n.localize("FQCARDENGINE.MacroErrorMsgNoTarget"));
  return;
}

// Infos de grille
const gridSize = canvas.grid.size;

// Vecteur lanceur -> cible : la direction de la projection
const dx = target.center.x - token.center.x;
const dy = target.center.y - token.center.y;
const len = Math.hypot(dx, dy);

// Le lanceur et la cible sur la même case : aucune direction à suivre
if (!len) {
  ui.notifications.error(game.i18n.localize("FQCARDENGINE.MacroErrorMsgNoPushDirection"));
  return;
}

// Chaque axe est arrondi à la case : la projection reste alignée sur la grille
const newPos = {
  x: target.position.x + Math.round((dx / len) * distance) * gridSize,
  y: target.position.y + Math.round((dy / len) * distance) * gridSize
};

// Séquence de projection : la bourrasque part du lanceur et emporte la cible
new Sequence()
  .effect()
    .file("jb2a.gust_of_wind.veryfast")
    .atLocation(token)
    .stretchTo(newPos)
    .elevation(0)
  .wait(100)
  .effect()
    .copySprite(target)
    .fadeIn(50)
    .duration(300)
    .fadeOut(150)
    .filter("Blur")
    .elevation(0)
  .animation()
    .on(target)
    .teleportTo(newPos)
    .snapToGrid()
    .waitUntilFinished()
  .effect()
    .file("jb2a.wind_lines.01.01.white")
    .atLocation(newPos)
    .scaleToObject()
  .play();
}
